trol custom-switch custom-control-appearance d-md-inline-block mr-3\"\n                :key=\"consentGroup.key\"\n              >\n                <input\n                  type=\"checkbox\"\n                  class=\"custom-control-input\"\n                  :id=\"_uid + '-group-' + consentGroup.key\"\n                  :disabled=\"consentGroup.necessary\"\n                  :checked=\"\n                    isConsented(consentGroup.key) || consentGroup.necessary\n                  \"\n                  @change=\"toggleConsent(consentGroup.key)\"\n                />\n                <label\n                  class=\"custom-control-label\"\n                  :for=\"_uid + '-group-' + consentGroup.key\"\n                >\n                  <template v-if=\"consentGroup.label.length > 0\">\n                    {{ consentGroup.label }}\n                  </template>\n                  <template v-else>\n                    {{\n                      $translate(\"Ceres::Template.privacySettingsDefaultGroup\")\n                    }}\n                  </template>\n                </label>\n              </span>\n            </template>\n\n            <a\n              href=\"#\"\n              class=\"text-primary text-appearance d-block d-md-inline-block\"\n              @click.prevent.stop=\"isExpanded = true\"\n              >{{ $translate(\"Ceres::Template.cookieBarMoreSettings\") }}</a\n            >\n          </div>\n        </div>\n        <div class=\"p-3 w-100\">\n          <button\n            class=\"btn btn-primary btn-block btn-appearance\"\n            @click=\"\n              acceptAll();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarAcceptAll\") }}\n          </button>\n          <button\n            class=\"btn btn-default btn-block\"\n            @click=\"\n              storeConsents();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarSave\") }}\n          </button>\n        </div>\n      </div>\n      <div class=\"row py-3\" v-if=\"isExpanded\" :class=\"classes\" :style=\"styles\">\n        <div class=\"col-12 mb-3\">\n          <privacy-settings :consent-groups=\"consentGroups\"></privacy-settings>\n        </div>\n        <div class=\"col-12 col-md-6\">\n          <a\n            href=\"#\"\n            class=\"text-primary text-appearance d-inline-block mb-3\"\n            @click.prevent.stop=\"isExpanded = false\"\n            >{{ $translate(\"Ceres::Template.cookieBarBack\") }}</a\n          >\n        </div>\n        <div class=\"col-6 col-md-3\">\n          <button\n            class=\"btn btn-block btn-primary btn-appearance\"\n            @click=\"\n              acceptAll();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarAcceptAll\") }}\n          </button>\n        </div>\n        <div class=\"col-6 col-md-3\">\n          <button\n            class=\"btn btn-block btn-block btn-default\"\n            @click=\"\n              storeConsents();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarSave\") }}\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- <div v-else>\n      <button\n        class=\"btn btn-primary btn-appearance\"\n        @click.prevent.stop=\"isCollapsed = false\"\n      >\n        <i class=\"fa fa-shield float-none\"></i>\n        <span class=\"d-none d-sm-inline-block\">{{\n          $translate(\"Ceres::Template.cookieBarPrivacySettings\")\n        }}</span>\n      </button>\n    </div> -->\n  </div>\n</template>\n\n<script>\nimport { mapMutations } from \"vuex\";\nimport { ComponentIdMixin } from \"../../mixins/componentId.mixin\";\n\nexport default {\n  props: {\n    styles: String,\n    classes: String,\n    consentGroups: Object,\n  },\n\n  data() {\n    return {\n      isCollapsed: true,\n      isExpanded: false,\n    };\n